#{item}

SELECT p.* FROM fund_financing_base_info_lib p
INNER JOIN (SELECT main_id AS financing_id, MAX(version) AS version FROM common_version t1
WHERE t1.module = 'FUND_FINANCING' AND version_type = 1
GROUP BY main_id) m ON p.origin_id = m.financing_id AND p.version = m.version
WHERE 1 = 1

    AND p.time_limit_type IN
    
        #{item}
    


    AND p.business_type IN
    
        #{item}
    


    AND p.actual_loan_date >= #{dto.startDate}


    AND p.actual_loan_date <= #{dto.endDate}


    AND p.actual_loan_date <= #{dto.actualLoanDateTo}


    AND p.financing_status != 'SETTLE'
